#!/bin/bash
function format_text {
    local style=$1
    case $style in
        "bold")
            echo "<b>Text</b>"
            ;;
        "italic")
            echo "<i>Text</i>"
            ;;
        "underline")
            echo "<u>Text</u>"
            ;;
        *)
            return 1
            ;;
    esac
}

formatted_text=$(format_text "strikethrough")
if [ $? -ne 0 ]; then
    echo "No default case for formatting text."
fi
